package com.blockchain.contracts

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class Transaction(val from: String, val to: String, val amount: Long, val nonce: Long)
data class AuthToken(val address: String, val timestamp: Long, val digest: ByteArray)

class CircuitBreaker(
    private val failureThreshold: Int = 5,
    private val resetTimeoutMs: Long = 60000
) {
    private val failureCount = AtomicInteger(0)
    private val lastFailureTime = AtomicLong(0)
    private val state = AtomicInteger(0) // 0=CLOSED, 1=OPEN, 2=HALF_OPEN

    fun isOpen(): Boolean {
        if (state.get() == 1) {
            if (System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs) {
                state.compareAndSet(1, 2)
                return false
            }
            return true
        }
        return false
    }

    fun recordSuccess() {
        failureCount.set(0)
        state.set(0)
    }

    fun recordFailure() {
        val count = failureCount.incrementAndGet()
        lastFailureTime.set(System.currentTimeMillis())
        if (count >= failureThreshold) {
            state.set(1)
        }
    }
}

class SmartContractEngine(
    private val contractSecret: ByteArray
) {
    private val balances = ConcurrentHashMap<String, Long>()
    private val nonces = ConcurrentHashMap<String, Long>()
    private val circuitBreaker = CircuitBreaker()
    private val authCache = ConcurrentHashMap<String, AuthToken>()

    init {
        balances["0x0000"] = 1_000_000L
    }

    fun computeAuthDigest(address: String, timestamp: Long): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(contractSecret, "HmacSHA256"))
        mac.update(address.toByteArray())
        mac.update(timestamp.toString().toByteArray())
        return mac.doFinal()
    }

    fun authenticate(address: String, providedDigest: ByteArray): AuthToken? {
        if (circuitBreaker.isOpen()) return null

        val cached = authCache[address]
        if (cached != null && isTokenFresh(cached)) {
            if (verifyDigest(cached.digest, providedDigest)) {
                circuitBreaker.recordSuccess()
                return cached
            }
        }

        val timestamp = System.currentTimeMillis()
        val expectedDigest = computeAuthDigest(address, timestamp)
        if (verifyDigest(expectedDigest, providedDigest)) {
            val token = AuthToken(address, timestamp, expectedDigest)
            authCache[address] = token
            circuitBreaker.recordSuccess()
            return token
        }

        circuitBreaker.recordFailure()
        return null
    }

    private fun verifyDigest(expected: ByteArray, provided: ByteArray): Boolean {
        return MessageDigest.isEqual(expected, provided)
    }

    private fun isTokenFresh(token: AuthToken): Boolean {
        return System.currentTimeMillis() - token.timestamp < 300_000
    }

    fun executeTransfer(token: AuthToken, tx: Transaction): Boolean {
        if (circuitBreaker.isOpen()) return false
        if (token.address != tx.from) return false

        val currentNonce = nonces.getOrDefault(tx.from, 0L)
        if (tx.nonce != currentNonce + 1) {
            circuitBreaker.recordFailure()
            return false
        }

        val senderBalance = balances.getOrDefault(tx.from, 0L)
        if (senderBalance < tx.amount || tx.amount <= 0) {
            circuitBreaker.recordFailure()
            return false
        }

        balances[tx.from] = senderBalance - tx.amount
        balances[tx.to] = balances.getOrDefault(tx.to, 0L) + tx.amount
        nonces[tx.from] = tx.nonce
        circuitBreaker.recordSuccess()
        return true
    }

    fun getBalance(address: String): Long = balances.getOrDefault(address, 0L)
}

fun main() {
    val engine = SmartContractEngine("super_secret_key_2024".toByteArray())
    val aliceAddress = "0xAlice"
    engine.javaClass.getDeclaredField("balances").let {
        it.isAccessible = true
        @Suppress("UNCHECKED_CAST")
        (it.get(engine) as ConcurrentHashMap<String, Long>)[aliceAddress] = 500L
    }
    val digest = engine.computeAuthDigest(aliceAddress, System.currentTimeMillis())
    val token = engine.authenticate(aliceAddress, digest)
    if (token != null) {
        val tx = Transaction(aliceAddress, "0xBob", 100L, 1L)
        println("Transfer result: ${engine.executeTransfer(token, tx)}")
        println("Alice balance: ${engine.getBalance(aliceAddress)}")
        println("Bob balance: ${engine.getBalance("0xBob")}")
    }
}
